// mu-plaits screens — a sketch of the macro wave (not the model's exact output), and the low-pass gate's strike.
const FONT = "8px ui-monospace, monospace";
const BLUE = "#3d7dff";
const GREEN = "#3ec96b";
const ORANGE = "#ff6a1a";
const GREY = "#6b6b6b";
const WHITE = "#ffffff";
const MODELS = ["VA+FILTER", "PHASE DIST", "6-OP FM 1", "6-OP FM 2", "6-OP FM 3", "WAVE TERRAIN", "STRING MACH", "CHIPTUNE", "VIRTUAL ANA", "WAVESHAPING", "2-OP FM", "GRAN FORMANT", "HARMONIC", "WAVETABLE", "CHORDS", "SPEECH", "SWARM", "FILT NOISE", "PART NOISE", "INHARM STR", "MODAL RES", "BASS DRUM", "SNARE DRUM", "HI-HAT"];

function num(p, k, d) {
  const v = p ? p[k] : undefined;
  return typeof v === "number" && Number.isFinite(v) ? v : d;
}
function clamp(v, a, b) {
  return Math.min(b, Math.max(a, v));
}

// Harmonics adds partials, Timbre bends the phase, Morph drives the sum toward a square.
function macro(ph, harm, timbre, morph) {
  const bent = Math.pow(ph, 1 + timbre * 3) * 2 * Math.PI;
  const count = 1 + Math.floor(harm * 11);
  let s = 0;
  for (let k = 1; k <= count; k++) s += Math.sin(bent * k) / k;
  return Math.tanh(s * (1 + morph * 6)) / Math.tanh(1 + morph * 6);
}

export default {
  osc(lcd) {
    const { ctx, width: W, height: H, params: p } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    ctx.font = FONT;
    ctx.lineWidth = 1;
    const harm = num(p, "Harmonics", 0.5);
    const timbre = num(p, "Timbre", 0.5);
    const morph = num(p, "Morph", 0.5);
    const model = Math.round(num(p, "Model", 0));
    const x0 = 4;
    const w = Math.max(1, W - 8);
    const top = 16;
    const mid = top + (H - top - 4) / 2;
    const half = Math.max(1, (H - top - 4) / 2);
    ctx.strokeStyle = GREY;
    ctx.beginPath();
    ctx.moveTo(x0, Math.round(mid) + 0.5);
    ctx.lineTo(x0 + w, Math.round(mid) + 0.5);
    ctx.stroke();
    ctx.strokeStyle = BLUE;
    ctx.beginPath();
    for (let i = 0; i <= w; i++) {
      const ph = ((i / w) * 2) % 1;
      const y = mid - clamp(macro(ph, harm, timbre, morph), -1, 1) * half;
      if (i === 0) ctx.moveTo(x0 + i, y);
      else ctx.lineTo(x0 + i, y);
    }
    ctx.stroke();
    ctx.fillStyle = WHITE;
    ctx.textAlign = "left";
    ctx.fillText(MODELS[model] ?? "VA+FILTER", 6, 10);
  },
  lpg(lcd) {
    const { ctx, width: W, height: H, params: p } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    ctx.font = FONT;
    ctx.lineWidth = 1;
    const decay = num(p, "Decay", 0.5);
    const colour = num(p, "LPG colour", 0.5);
    const ping = Math.round(num(p, "Envelope", 0)) === 1;
    const x0 = 4;
    const w = Math.max(1, W - 8);
    const top = 16;
    const bot = H - 6;
    const hh = Math.max(1, bot - top);
    const tau = 0.03 + decay * decay * 0.6;
    const env = (t) => (ping ? Math.exp(-t / tau) : t < 0.45 ? 1 : Math.exp(-(t - 0.45) / tau));
    const draw = (color, fn) => {
      ctx.strokeStyle = color;
      ctx.beginPath();
      for (let i = 0; i <= w; i++) {
        const y = bot - clamp(fn(i / w), 0, 1) * hh;
        if (i === 0) ctx.moveTo(x0 + i, y);
        else ctx.lineTo(x0 + i, y);
      }
      ctx.stroke();
    };
    draw(GREEN, (t) => 1 - colour + colour * env(t));
    draw(ORANGE, (t) => Math.pow(env(t), 1 - colour * 0.6));
    ctx.textAlign = "left";
    ctx.fillStyle = WHITE;
    ctx.fillText(ping ? "PING" : "GATE", 6, 10);
    ctx.textAlign = "right";
    ctx.fillStyle = ORANGE;
    ctx.fillText("AMP", W - 26, 10);
    ctx.fillStyle = GREEN;
    ctx.fillText("LPF", W - 6, 10);
  },
};

// mu-braids screens — the wave crushed by Bits and Sample rate, and the voice's ADSR.
const FONT = "8px ui-monospace, monospace";
const BLUE = "#3d7dff";
const RED = "#ff3b30";
const ORANGE = "#ff6a1a";
const GREY = "#6b6b6b";
const WHITE = "#ffffff";
const BITS = [2, 3, 4, 6, 8, 12, 16];
const RATES = [4, 8, 16, 24, 32, 48, 96];
const STEPS = [10, 16, 28, 40, 54, 80, 0];

function num(p, k, d) {
  const v = p ? p[k] : undefined;
  return typeof v === "number" && Number.isFinite(v) ? v : d;
}
function clamp(v, a, b) {
  return Math.min(b, Math.max(a, v));
}
function glass(ctx, W, H) {
  ctx.fillStyle = "#000";
  ctx.fillRect(0, 0, W, H);
  ctx.font = FONT;
  ctx.lineWidth = 1;
}




function adsr(ctx, W, H, a, d, s, r) {
  const wa = Math.sqrt(a / 2);
  const wd = Math.sqrt(d / 4);
  const wr = Math.sqrt(r / 8);
  const hold = 0.5;
  const total = wa + wd + hold + wr || 1;
  const x0 = 6;
  const w = Math.max(1, W - 12);
  const top = 16;
  const bot = H - 14;
  const hh = Math.max(1, bot - top);
  const xa = x0 + (wa / total) * w;
  const xd = xa + (wd / total) * w;
  const xs = xd + (hold / total) * w;
  const xr = x0 + w;
  const ys = bot - s * hh;
  ctx.strokeStyle = GREY;
  ctx.beginPath();
  ctx.moveTo(x0, Math.round(bot) + 0.5);
  ctx.lineTo(xr, Math.round(bot) + 0.5);
  ctx.stroke();
  ctx.strokeStyle = ORANGE;
  ctx.beginPath();
  ctx.moveTo(x0, bot);
  const steps = 24;
  for (let i = 1; i <= steps; i++) ctx.lineTo(x0 + ((xa - x0) * i) / steps, bot - hh * (1 - Math.pow(1 - i / steps, 2)));
  for (let i = 1; i <= steps; i++) ctx.lineTo(xa + ((xd - xa) * i) / steps, ys - (ys - top) * Math.exp((-4 * i) / steps) + (ys - top) * Math.exp(-4) * (i / steps));
  ctx.lineTo(xs, ys);
  for (let i = 1; i <= steps; i++) ctx.lineTo(xs + ((xr - xs) * i) / steps, bot - (bot - ys) * (Math.exp((-4 * i) / steps) - Math.exp(-4) * (i / steps)));
  ctx.stroke();
  ctx.fillStyle = WHITE;
  for (const [x, y] of [[xa, top], [xd, ys], [xs, ys]]) ctx.fillRect(x - 1.5, y - 1.5, 3, 3);
  ctx.fillStyle = GREY;
  ctx.textAlign = "center";
  ctx.fillText("A", (x0 + xa) / 2, H - 4);
  ctx.fillText("D", (xa + xd) / 2, H - 4);
  ctx.fillText("S", (xd + xs) / 2, H - 4);
  ctx.fillText("R", (xs + xr) / 2, H - 4);
}

function secs(t) {
  return t < 1 ? `${Math.round(t * 1000)}MS` : `${t.toFixed(2)}S`;
}

// Timbre sharpens a sine toward a saw, Color folds it; a sketch of the macro, not the shape's exact output.
function macro(ph, timbre, color) {
  const saw = ph * 2 - 1;
  const sine = Math.sin(ph * 2 * Math.PI);
  const v = sine + (saw - sine) * timbre;
  return Math.sin(v * (1 + color * 4) * 1.2) / Math.max(0.2, Math.sin(Math.min(1.5, 1.2 * (1 + color * 4))));
}

export default {
  wave(lcd) {
    const { ctx, width: W, height: H, params: p } = lcd;
    glass(ctx, W, H);
    const timbre = num(p, "Timbre", 0.5);
    const color = num(p, "Color", 0.5);
    const bi = clamp(Math.round(num(p, "Bits", 6)), 0, 6);
    const ri = clamp(Math.round(num(p, "Sample rate", 5)), 0, 6);
    const levels = Math.pow(2, BITS[bi] ?? 16) / 2;
    const x0 = 4;
    const w = Math.max(1, W - 8);
    const top = 16;
    const mid = top + (H - top - 4) / 2;
    const half = Math.max(1, (H - top - 4) / 2);
    const cycles = 2;
    const steps = STEPS[ri] ?? 0;
    ctx.strokeStyle = GREY;
    ctx.beginPath();
    ctx.moveTo(x0, Math.round(mid) + 0.5);
    ctx.lineTo(x0 + w, Math.round(mid) + 0.5);
    ctx.stroke();
    const sample = (u) => {
      const held = steps > 0 ? Math.floor(u * steps * cycles) / (steps * cycles) : u;
      const v = clamp(macro((held * cycles) % 1, timbre, color), -1, 1);
      return Math.round(v * levels) / levels;
    };
    ctx.strokeStyle = BLUE;
    ctx.beginPath();
    let last = 0;
    for (let i = 0; i <= w; i++) {
      const y = mid - clamp(sample(i / w), -1, 1) * half;
      if (i === 0) ctx.moveTo(x0, y);
      else {
        ctx.lineTo(x0 + i, last);
        ctx.lineTo(x0 + i, y);
      }
      last = y;
    }
    ctx.stroke();
    ctx.textAlign = "left";
    ctx.fillStyle = WHITE;
    ctx.fillText("OSC", 6, 10);
    ctx.textAlign = "right";
    ctx.fillStyle = RED;
    ctx.fillText(`${BITS[bi] ?? 16}BIT ${RATES[ri] ?? 48}K`, W - 6, 10);
  },
  env(lcd) {
    const { ctx, width: W, height: H, params: p } = lcd;
    glass(ctx, W, H);
    const a = num(p, "Attack", 0.002);
    const d = num(p, "Decay", 0.3);
    const s = clamp(num(p, "Sustain", 0.8), 0, 1);
    const r = num(p, "Release", 0.3);
    adsr(ctx, W, H, a, d, s, r);
    ctx.fillStyle = WHITE;
    ctx.textAlign = "left";
    ctx.fillText("ENV", 6, 10);
    ctx.textAlign = "right";
    ctx.fillStyle = ORANGE;
    ctx.fillText(`${secs(a)} ${secs(d)} ${Math.round(s * 100)}% ${secs(r)}`, W - 6, 10);
  },
};

// mu-rings screen — the resonator's partials: grey as struck, green as they still ring once damped.
const FONT = "8px ui-monospace, monospace";
const GREEN = "#3ec96b";
const GREY = "#6b6b6b";
const WHITE = "#ffffff";
const MODELS = ["MODAL", "SYMP STR", "STRING", "FM VOICE", "SYMP QUANT", "STRING+VERB", "FORMANT", "CHORUS", "REVERB", "FORMANT 2", "ENSEMBLE", "REVERB 2"];
const POLY = ["1", "2", "4"];

function num(p, k, d) {
  const v = p ? p[k] : undefined;
  return typeof v === "number" && Number.isFinite(v) ? v : d;
}
function clamp(v, a, b) {
  return Math.min(b, Math.max(a, v));
}

export default {
  partials(lcd) {
    const { ctx, width: W, height: H, params: p, output, state } = lcd;
    ctx.fillStyle = "#000";
    ctx.fillRect(0, 0, W, H);
    ctx.font = FONT;
    ctx.lineWidth = 1;
    const structure = num(p, "Structure", 0.5);
    const bright = num(p, "Brightness", 0.5);
    const damp = num(p, "Damping", 0.5);
    const pos = num(p, "Position", 0.5);
    const model = Math.round(num(p, "Model", 0));
    const poly = Math.round(num(p, "Polyphony", 0));
    const harmonic = model === 2 || model === 5;
    const x0 = 6;
    const w = Math.max(1, W - 12);
    const top = 16;
    const bot = H - 6;
    const hh = Math.max(1, bot - top);
    const count = 24;
    const maxRatio = Math.log(40);
    const strike = 0.05 + pos * 0.45;
    let peak = 0;
    if (Array.isArray(output)) for (let i = Math.max(0, output.length - 8); i < output.length; i++) peak = Math.max(peak, output[i] ?? 0);
    state.glow = Math.max(clamp(peak, 0, 1), (state.glow ?? 0) * 0.8);
    for (let k = 1; k <= count; k++) {
      const stretch = harmonic ? structure * 0.004 : (structure - 0.3) * 0.03;
      const ratio = k * Math.sqrt(Math.max(0.05, 1 + stretch * k * k));
      const x = x0 + (Math.log(Math.max(1, ratio)) / maxRatio) * w;
      if (x > x0 + w) continue;
      const comb = Math.abs(Math.sin(Math.PI * k * strike));
      const tilt = Math.pow(k, -(1 - bright) * 1.6);
      const a = clamp(comb * tilt, 0, 1);
      const left = a * Math.exp(-(k - 1) * (0.02 + damp * 0.25));
      const xr = Math.round(x) + 0.5;
      ctx.strokeStyle = GREY;
      ctx.beginPath();
      ctx.moveTo(xr, bot);
      ctx.lineTo(xr, bot - a * hh);
      ctx.stroke();
      ctx.fillStyle = GREEN;
      const h = left * hh;
      ctx.fillRect(xr - 1.5, bot - h, 3, h);
    }
    ctx.textAlign = "left";
    ctx.fillStyle = WHITE;
    ctx.fillText(MODELS[model] ?? "MODAL", 6, 10);
    ctx.textAlign = "right";
    ctx.fillStyle = GREY;
    ctx.fillText(`POLY ${POLY[poly] ?? "1"}`, W - 6, 10);
    const g = state.glow ?? 0;
    if (g > 0.02) {
      ctx.fillStyle = GREEN;
      ctx.globalAlpha = clamp(g, 0, 1);
      ctx.beginPath();
      ctx.arc(W - 52, 7, 2.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1;
    }
  },
};
